        _lang() {
            try {
                var lang = (window.mySimulation && window.mySimulation.language) || document.documentElement.lang || 'en';
                if (String(lang).indexOf('es') === 0) return 'es';
            } catch(e) {}
            return 'en';
        }

        _t(obj) {
            var l = this._lang();
            return (obj && obj[l]) ? obj[l] : (obj && obj['en']) ? obj['en'] : '';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    aiAdoption: 25,
                    employeeEngagement: 65,
                    productivityGains: 10,
                    changeSustainability: 40,
                    overallScore: 35,
                    aiAdoptionHistory: [],
                    engagementHistory: [],
                    productivityHistory: [],
                    sustainabilityHistory: [],
                    overallScoreHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    d1: 0,
                    d2: 0,
                    d3: 0,
                    d4: 0,
                    eventResponse: 0
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = this._t(round.title);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.textContent = this._t(round.briefing);

            for (var di = 0; di < 4; di++) {
                var dec = round.decisions[di];
                var labelEl = document.getElementById('decisionLabel' + (di + 1));
                if (labelEl) labelEl.textContent = this._t(dec.label);

                var selEl = document.getElementById('decision' + (di + 1));
                if (selEl) {
                    selEl.innerHTML = '';
                    for (var oi = 0; oi < dec.options.length; oi++) {
                        var opt = document.createElement('option');
                        opt.value = oi;
                        opt.textContent = this._t(dec.options[oi].text);
                        selEl.appendChild(opt);
                    }
                }
            }

            var eventTextEl = document.getElementById('eventText');
            if (eventTextEl) eventTextEl.textContent = this._t(round.event.text);

            var evtSel = document.getElementById('eventResponse');
            if (evtSel) {
                evtSel.innerHTML = '';
                for (var ri = 0; ri < round.event.responses.length; ri++) {
                    var ropt = document.createElement('option');
                    ropt.value = ri;
                    ropt.textContent = this._t(round.event.responses[ri].text);
                    evtSel.appendChild(ropt);
                }
            }
        }

        validateDecisions(decisions) {
            var sel1 = document.getElementById('decision1');
            var sel2 = document.getElementById('decision2');
            var sel3 = document.getElementById('decision3');
            var sel4 = document.getElementById('decision4');
            var evtSel = document.getElementById('eventResponse');

            if (sel1) decisions.d1 = parseInt(sel1.value);
            if (sel2) decisions.d2 = parseInt(sel2.value);
            if (sel3) decisions.d3 = parseInt(sel3.value);
            if (sel4) decisions.d4 = parseInt(sel4.value);
            if (evtSel) decisions.eventResponse = parseInt(evtSel.value);

            return true;
        }

        calculateResults(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var d = state.decisions;
            var ds = state.domainState;

            var dAdopt = 0, dEngage = 0, dProd = 0, dSustain = 0;

            var choices = [d.d1, d.d2, d.d3, d.d4];
            for (var i = 0; i < 4; i++) {
                var optIdx = Math.min(Math.max(choices[i] || 0, 0), 2);
                var imp = round.decisions[i].options[optIdx].impact;
                dAdopt += imp[0];
                dEngage += imp[1];
                dProd += imp[2];
                dSustain += imp[3];
            }

            var evtIdx = Math.min(Math.max(d.eventResponse || 0, 0), 2);
            var evtImp = round.event.responses[evtIdx].impact;
            dAdopt += evtImp[0];
            dEngage += evtImp[1];
            dProd += evtImp[2];
            dSustain += evtImp[3];

            ds.aiAdoption = Math.min(100, Math.max(0, ds.aiAdoption + dAdopt));
            ds.employeeEngagement = Math.min(100, Math.max(0, ds.employeeEngagement + dEngage));
            ds.productivityGains = Math.min(100, Math.max(0, ds.productivityGains + dProd));
            ds.changeSustainability = Math.min(100, Math.max(0, ds.changeSustainability + dSustain));

            var overall = Math.round((ds.aiAdoption + ds.employeeEngagement + ds.productivityGains + ds.changeSustainability) / 4);
            ds.overallScore = overall;

            // platform score: same overall composite that getPerformanceSummary uses for the final verdict, already 0-100, clamped defensively
            var overallScore = Math.max(0, Math.min(100, overall));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            ds.aiAdoptionHistory.push(Math.round(ds.aiAdoption));
            ds.engagementHistory.push(Math.round(ds.employeeEngagement));
            ds.productivityHistory.push(Math.round(ds.productivityGains));
            ds.sustainabilityHistory.push(Math.round(ds.changeSustainability));
            ds.overallScoreHistory.push(overall);

            // Render next round synchronously (no setTimeout race).
            this._updateBriefing({ currentPeriod: (state.currentPeriod || 1) + 1 });

            return {
                period: state.currentPeriod,
                aiAdoption: Math.round(ds.aiAdoption),
                employeeEngagement: Math.round(ds.employeeEngagement),
                productivityGains: Math.round(ds.productivityGains),
                changeSustainability: Math.round(ds.changeSustainability),
                overall: overall,
                dAdopt: dAdopt,
                dEngage: dEngage,
                dProd: dProd,
                dSustain: dSustain
            };
        }

