        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var overall = r.overall || 0;

            var t = function(k) { return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k; };
            var performance = t('perf_needs');
            if (overall >= 85) performance = t('perf_excellent');
            else if (overall >= 75) performance = t('perf_strong');
            else if (overall >= 65) performance = t('perf_good');
            else if (overall >= 55) performance = t('perf_mixed');

            var insights = [];
            if (r.aiAdoption >= 80) insights.push(t('ins_adopt_high'));
            if (r.aiAdoption < 50) insights.push(t('ins_adopt_low'));
            if (r.employeeEngagement >= 80) insights.push(t('ins_engage_high'));
            if (r.employeeEngagement < 50) insights.push(t('ins_engage_low'));
            if (r.productivityGains >= 70) insights.push(t('ins_prod_high'));
            if (r.productivityGains < 40) insights.push(t('ins_prod_low'));
            if (r.changeSustainability >= 80) insights.push(t('ins_sustain_high'));
            if (r.changeSustainability < 50) insights.push(t('ins_sustain_low'));

            return {
                overall: overall,
                aiAdoption: r.aiAdoption,
                employeeEngagement: r.employeeEngagement,
                productivityGains: r.productivityGains,
                changeSustainability: r.changeSustainability,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.dEngage < -5) return window.mySimulation.t('hint_engagement_drop');
            if (results.dSustain < -5) return window.mySimulation.t('hint_sustainability_drop');
            if (results.overall < 40) return window.mySimulation.t('hint_low_overall');
            if (results.dAdopt > 10 && results.dEngage > 5) return window.mySimulation.t('hint_balanced');
            return null;
        }

